// Word finder algorithm
const MAX_MOVES = 5000; // Limit to prevent memory issues

// Debug function to check board state
function debugBoardState() {
    console.log('=== DEBUG BOARD STATE ===');
    console.log('window.boardState exists:', !!window.boardState);
    if (window.boardState) {
        console.log('Board dimensions:', window.boardState.length, 'x', (window.boardState[0] ? window.boardState[0].length : 'undefined'));
        let filledCount = 0;
        for (let r = 0; r < 15; r++) {
            for (let c = 0; c < 15; c++) {
                if (window.boardState[r] && window.boardState[r][c]) {
                    filledCount++;
                    console.log(`  Tile at (${r},${c}): "${window.boardState[r][c]}"`);
                }
            }
        }
        console.log('Total filled cells:', filledCount);
    }
    console.log('=========================');
}

// Make it globally accessible for debugging
window.debugBoardState = debugBoardState;

function findAllMoves(playerTiles) {
    const moves = [];
    // Ensure board state exists and is 15x15 so we never throw
    if (typeof window === 'undefined') return moves;
    if (!window.boardState || !Array.isArray(window.boardState) || window.boardState.length !== 15) {
        window.boardState = Array(15).fill(null).map(function() { return Array(15).fill(null); });
    }
    const tiles = playerTiles.toUpperCase().split('');
    
    // Check if board is empty (first move)
    const boardEmpty = isBoardEmpty();
    
    if (boardEmpty) {
        // First move must go through center (7 = center of 15x15 board)
        findMovesAtPosition(7, 7, tiles, moves, true);
    } else {
        // Find all anchor squares (empty squares adjacent to filled squares)
        const anchors = findAnchors();
        
        for (const [row, col] of anchors) {
            if (moves.length >= MAX_MOVES) break; // Stop if we have enough moves
            findMovesAtPosition(row, col, tiles, moves, false);
        }
    }
    
    // Sort by score descending
    moves.sort((a, b) => b.score - a.score);
    
    // Remove duplicates and limit results
    const seen = new Set();
    const uniqueMoves = [];
    for (const move of moves) {
        const key = `${move.word}-${move.row}-${move.col}-${move.direction}`;
        if (!seen.has(key)) {
            // Final validation: verify move actually connects to existing tiles
            if (!validateMoveConnectivity(move)) continue;
            
            seen.add(key);
            uniqueMoves.push(move);
            if (uniqueMoves.length >= 1000) break; // Return top 1000 unique moves
        }
    }
    return uniqueMoves;
}

// Final validation to ensure a move properly connects to existing board tiles
function validateMoveConnectivity(move) {
    const { word, row, col, direction, newTiles } = move;
    const isHorizontal = direction === 'H';
    
    // Safety check: ensure boardState exists
    if (!window.boardState) {
        console.error('validateMoveConnectivity: window.boardState is undefined!');
        return false;
    }
    
    // First move (empty board): accept all moves that createMove already validated
    if (isBoardEmpty()) return true;
    
    // First verify: all positions where we place new tiles must be empty
    for (const i of newTiles) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        if (window.boardState[r] && window.boardState[r][c]) {
            console.log(`Rejecting ${word}: position ${r},${c} is occupied`);
            return false; // Trying to place tile on occupied square
        }
    }
    
    // Second verify: if word uses existing tiles, they must match
    for (let i = 0; i < word.length; i++) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        if (window.boardState[r][c] && window.boardState[r][c] !== word[i]) {
            return false; // Word letter doesn't match existing tile
        }
    }
    
    // Third verify: at least one new tile must be adjacent to an existing tile
    // (unless it's the first move — empty board — in which case skip this)
    let boardHasAnyTile = false;
    for (let r = 0; r < 15 && !boardHasAnyTile; r++) {
        for (let c = 0; c < 15 && !boardHasAnyTile; c++) {
            if (window.boardState[r] && window.boardState[r][c]) boardHasAnyTile = true;
        }
    }
    if (boardHasAnyTile && newTiles.length === word.length) {
        // All tiles are new and board isn't empty — must have at least one adjacent to existing
        let hasConnection = false;
        for (const i of newTiles) {
            const r = isHorizontal ? row : row + i;
            const c = isHorizontal ? col + i : col;
            
            const adjacent = [
                [r - 1, c], [r + 1, c], [r, c - 1], [r, c + 1]
            ];
            
            for (const [ar, ac] of adjacent) {
                if (ar >= 0 && ar < 15 && ac >= 0 && ac < 15) {
                    if (window.boardState[ar] && window.boardState[ar][ac]) {
                        hasConnection = true;
                        break;
                    }
                }
            }
            if (hasConnection) break;
        }
        if (!hasConnection) {
            console.log(`Rejecting ${word} at ${row},${col} ${direction}: no connection to existing tiles`);
            return false;
        }
    }
    
    return true;
}

function isBoardEmpty() {
    const board = window.boardState;
    if (!board || !board.length) return true;
    for (let r = 0; r < 15; r++) {
        for (let c = 0; c < 15; c++) {
            if (board[r] && board[r][c]) return false;
        }
    }
    return true;
}

function findAnchors() {
    const anchors = [];
    const board = window.boardState;
    if (!board || !board.length) return anchors;
    for (let r = 0; r < 15; r++) {
        for (let c = 0; c < 15; c++) {
            if (!board[r] || !board[r][c]) {
                if (hasAdjacentTile(r, c)) anchors.push([r, c]);
            }
        }
    }
    return anchors;
}

function hasAdjacentTile(row, col) {
    const board = window.boardState;
    if (!board || !board.length) return false;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    for (const [dr, dc] of dirs) {
        const nr = row + dr;
        const nc = col + dc;
        if (nr >= 0 && nr < 15 && nc >= 0 && nc < 15 && board[nr] && board[nr][nc]) {
            return true;
        }
    }
    return false;
}

function findMovesAtPosition(row, col, tiles, moves, isFirstMove) {
    // Try horizontal words
    findWordsInDirection(row, col, tiles, moves, 'H', isFirstMove);
    // Try vertical words
    findWordsInDirection(row, col, tiles, moves, 'V', isFirstMove);
}

function findWordsInDirection(anchorRow, anchorCol, tiles, moves, direction, isFirstMove) {
    const isHorizontal = direction === 'H';
    
    // Get the prefix (letters already on board before anchor)
    let prefixLetters = '';
    let startPos = isHorizontal ? anchorCol : anchorRow;
    
    while (startPos > 0) {
        const r = isHorizontal ? anchorRow : startPos - 1;
        const c = isHorizontal ? startPos - 1 : anchorCol;
        if (window.boardState[r][c]) {
            prefixLetters = window.boardState[r][c] + prefixLetters;
            startPos--;
        } else {
            break;
        }
    }
    
    // Try extending with available tiles (empty Set for blank positions)
    tryExtend(anchorRow, anchorCol, startPos, prefixLetters, tiles.slice(), moves, direction, isFirstMove, new Set());
    
    // Also try "left extensions" - placing tiles BEFORE the current start position
    // This finds words that start with player tiles before existing board tiles
    if (startPos > 0 && prefixLetters.length === 0) {
        // Count how many empty squares we can use before the anchor
        let leftLimit = 0;
        let checkPos = (isHorizontal ? anchorCol : anchorRow) - 1;
        while (checkPos >= 0 && leftLimit < tiles.length) {
            const r = isHorizontal ? anchorRow : checkPos;
            const c = isHorizontal ? checkPos : anchorCol;
            if (window.boardState[r][c]) break; // Hit existing tile
            leftLimit++;
            checkPos--;
        }
        
        // Count blanks - limit left extensions more aggressively with multiple blanks
        const blankCount = tiles.filter(t => t === '?').length;
        const maxLeftExtension = blankCount >= 2 ? Math.min(leftLimit, 4) : Math.min(leftLimit, tiles.length);
        
        // Try placing 1 to maxLeftExtension tiles before the anchor
        for (let numLeft = 1; numLeft <= maxLeftExtension; numLeft++) {
            tryLeftExtension(anchorRow, anchorCol, numLeft, '', tiles.slice(), moves, direction, isFirstMove, new Set());
        }
    }
}

function tryLeftExtension(anchorRow, anchorCol, remainingLeft, currentPrefix, remainingTiles, moves, direction, isFirstMove, blankPositions) {
    const isHorizontal = direction === 'H';
    const anchorPos = isHorizontal ? anchorCol : anchorRow;
    
    if (remainingLeft === 0) {
        // Validate the complete prefix before proceeding
        // The prefix must be the start of at least one valid word
        if (currentPrefix.length > 0 && !isValidPrefix(currentPrefix)) {
            return; // This prefix doesn't lead to any valid words
        }
        
        // Now extend right from the anchor using the prefix we built
        const startPos = anchorPos - currentPrefix.length;
        tryExtend(anchorRow, anchorCol, startPos, currentPrefix, remainingTiles, moves, direction, isFirstMove, blankPositions);
        return;
    }
    
    // Position where we're placing the next left tile
    const leftPos = anchorPos - (currentPrefix.length + 1);
    if (leftPos < 0) return;
    
    const r = isHorizontal ? anchorRow : leftPos;
    const c = isHorizontal ? leftPos : anchorCol;
    
    // Can't place a tile where one already exists
    if (window.boardState[r][c]) return;
    
    // Try each available tile
    const usedIndices = new Set();
    for (let i = 0; i < remainingTiles.length; i++) {
        const tile = remainingTiles[i];
        if (usedIndices.has(tile + i)) continue;
        usedIndices.add(tile + i);
        
        const isBlank = tile === '?';
        const lettersToTry = isBlank ? 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('') : [tile];
        
        for (const letter of lettersToTry) {
            // Check cross-word validity at this position
            if (!isValidCrossWord(r, c, letter, direction)) continue;
            
            const newPrefix = letter + currentPrefix;
            
            const newRemaining = remainingTiles.slice();
            newRemaining.splice(i, 1);
            
            // Shift existing blank positions right by 1 since we're prepending
            const newBlankPositions = new Set();
            for (const pos of blankPositions) {
                newBlankPositions.add(pos + 1);
            }
            // Add new blank at position 0 if this tile is a blank
            if (isBlank) {
                newBlankPositions.add(0);
            }
            
            tryLeftExtension(anchorRow, anchorCol, remainingLeft - 1, newPrefix, newRemaining, moves, direction, isFirstMove, newBlankPositions);
        }
    }
}

function tryExtend(anchorRow, anchorCol, startPos, currentWord, remainingTiles, moves, direction, isFirstMove, blankPositions) {
    const isHorizontal = direction === 'H';
    const pos = isHorizontal ? anchorCol : anchorRow;
    const wordLen = currentWord.length;
    const currentPos = startPos + wordLen;
    
    // Check if we've gone past the anchor
    if (currentPos > (isHorizontal ? anchorCol : anchorRow)) {
        // We're past the anchor, now we can check validity
        if (currentWord.length >= 2 && DICTIONARY.has(currentWord)) {
            const move = createMove(anchorRow, anchorCol, startPos, currentWord, direction, isFirstMove, blankPositions);
            if (move) {
                moves.push(move);
            }
        }
    }
    
    // Try to extend further
    if (currentPos < 15) {
        const r = isHorizontal ? anchorRow : currentPos;
        const c = isHorizontal ? currentPos : anchorCol;
        const cell = (window.boardState && window.boardState[r]) ? window.boardState[r][c] : null;
        
        if (cell) {
            // There's already a tile here, use it
            const newWord = currentWord + cell;
            if (isValidPrefix(newWord)) {
                tryExtend(anchorRow, anchorCol, startPos, newWord, remainingTiles, moves, direction, isFirstMove, blankPositions);
            }
        } else {
            // Try placing each available tile
            const usedIndices = new Set();
            for (let i = 0; i < remainingTiles.length; i++) {
                const tile = remainingTiles[i];
                if (usedIndices.has(tile + i)) continue;
                usedIndices.add(tile + i);
                
                const isBlank = tile === '?';
                const lettersToTry = isBlank ? 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('') : [tile];
                
                for (const letter of lettersToTry) {
                    const newWord = currentWord + letter;
                    
                    // Check cross-word validity
                    if (!isValidCrossWord(r, c, letter, direction)) continue;
                    
                    if (isValidPrefix(newWord)) {
                        const newRemaining = remainingTiles.slice();
                        newRemaining.splice(i, 1);
                        
                        // Track blank positions (position in word = currentWord.length = index of new letter)
                        const newBlankPositions = new Set(blankPositions);
                        if (isBlank) {
                            newBlankPositions.add(currentWord.length);
                        }
                        
                        tryExtend(anchorRow, anchorCol, startPos, newWord, newRemaining, moves, direction, isFirstMove, newBlankPositions);
                    }
                }
            }
        }
    }
    
    // Also check current word if valid
    if (currentWord.length >= 2 && DICTIONARY.has(currentWord) && currentPos > (isHorizontal ? anchorCol : anchorRow)) {
        const move = createMove(anchorRow, anchorCol, startPos, currentWord, direction, isFirstMove, blankPositions);
        if (move && !moves.some(m => m.word === move.word && m.row === move.row && m.col === move.col && m.direction === move.direction)) {
            moves.push(move);
        }
    }
}

function isValidPrefix(prefix) {
    // Use the precomputed prefix set for O(1) lookup
    return PREFIXES.has(prefix);
}

function isValidCrossWord(row, col, letter, mainDirection) {
    const isHorizontal = mainDirection === 'H';
    
    // Check perpendicular direction
    let crossWord = letter;
    let hasAdjacent = false;
    
    // Look backwards
    let pos = isHorizontal ? row - 1 : col - 1;
    while (pos >= 0) {
        const r = isHorizontal ? pos : row;
        const c = isHorizontal ? col : pos;
        if (window.boardState[r][c]) {
            crossWord = window.boardState[r][c] + crossWord;
            hasAdjacent = true;
            pos--;
        } else {
            break;
        }
    }
    
    // Look forwards
    pos = isHorizontal ? row + 1 : col + 1;
    while (pos < 15) {
        const r = isHorizontal ? pos : row;
        const c = isHorizontal ? col : pos;
        if (window.boardState[r][c]) {
            crossWord = crossWord + window.boardState[r][c];
            hasAdjacent = true;
            pos++;
        } else {
            break;
        }
    }
    
    // If there's no adjacent tiles in cross direction, it's valid
    if (!hasAdjacent) return true;
    
    // Otherwise, the cross word must be valid
    return DICTIONARY.has(crossWord);
}

function createMove(anchorRow, anchorCol, startPos, word, direction, isFirstMove, blankPositions = new Set()) {
    const isHorizontal = direction === 'H';
    const row = isHorizontal ? anchorRow : startPos;
    const col = isHorizontal ? startPos : anchorCol;
    
    // Validate placement
    const endPos = startPos + word.length - 1;
    if (endPos >= 15) return null;
    
    // Check that word doesn't start in the middle of existing tiles
    if (startPos > 0) {
        const beforeR = isHorizontal ? row : startPos - 1;
        const beforeC = isHorizontal ? startPos - 1 : col;
        if (window.boardState[beforeR][beforeC]) return null;
    }
    
    // Check that word doesn't end in the middle of existing tiles
    if (endPos < 15 - 1) {
        const afterR = isHorizontal ? row : endPos + 1;
        const afterC = isHorizontal ? endPos + 1 : col;
        if (window.boardState[afterR][afterC]) return null;
    }
    
    // For first move, must pass through center
    if (isFirstMove) {
        let passesCenter = false;
        for (let i = 0; i < word.length; i++) {
            const r = isHorizontal ? row : row + i;
            const c = isHorizontal ? col + i : col;
            if (r === 7 && c === 7) {
                passesCenter = true;
                break;
            }
        }
        if (!passesCenter) return null;
    }
    
    // Track which positions are new tiles and validate existing tiles match
    const newTiles = [];
    for (let i = 0; i < word.length; i++) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        const existingTile = window.boardState[r][c];
        
        if (existingTile) {
            // If there's an existing tile, it must match the letter in our word
            if (existingTile !== word[i]) return null;
        } else {
            newTiles.push(i);
        }
    }
    
    // Must use at least one new tile
    if (newTiles.length === 0) return null;
    
    // Validate ALL cross-words formed by new tiles
    // Also track if any new tile is adjacent to existing tiles (for connectivity)
    let hasConnectionToBoard = (newTiles.length < word.length); // Connected if using existing tiles
    
    for (const i of newTiles) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        const letter = word[i];
        
        // Build the cross-word in the perpendicular direction
        let crossWord = letter;
        let hasAdjacent = false;
        
        // For a horizontal main word, check vertically (up/down)
        // For a vertical main word, check horizontally (left/right)
        
        if (isHorizontal) {
            // Check up
            let checkR = r - 1;
            while (checkR >= 0 && window.boardState[checkR][c]) {
                crossWord = window.boardState[checkR][c] + crossWord;
                hasAdjacent = true;
                checkR--;
            }
            // Check down
            checkR = r + 1;
            while (checkR < 15 && window.boardState[checkR][c]) {
                crossWord = crossWord + window.boardState[checkR][c];
                hasAdjacent = true;
                checkR++;
            }
        } else {
            // Check left
            let checkC = c - 1;
            while (checkC >= 0 && window.boardState[r][checkC]) {
                crossWord = window.boardState[r][checkC] + crossWord;
                hasAdjacent = true;
                checkC--;
            }
            // Check right  
            checkC = c + 1;
            while (checkC < 15 && window.boardState[r][checkC]) {
                crossWord = crossWord + window.boardState[r][checkC];
                hasAdjacent = true;
                checkC++;
            }
        }
        
        // If cross-word was formed, it must be valid
        if (hasAdjacent) {
            hasConnectionToBoard = true;
            if (!DICTIONARY.has(crossWord)) {
                return null;
            }
        }
    }
    
    // Double-check connectivity: at least one new tile must be adjacent to an existing tile
    // Check all 4 directions for each new tile
    if (!hasConnectionToBoard) {
        for (const i of newTiles) {
            const r = isHorizontal ? row : row + i;
            const c = isHorizontal ? col + i : col;
            
            // Check all 4 adjacent cells
            const adjacentPositions = [
                [r - 1, c], // up
                [r + 1, c], // down
                [r, c - 1], // left
                [r, c + 1]  // right
            ];
            
            for (const [ar, ac] of adjacentPositions) {
                if (ar >= 0 && ar < 15 && ac >= 0 && ac < 15) {
                    if (window.boardState[ar][ac]) {
                        hasConnectionToBoard = true;
                        break;
                    }
                }
            }
            if (hasConnectionToBoard) break;
        }
    }
    
    // The word must connect to the existing board
    if (!isFirstMove && !hasConnectionToBoard) {
        return null;
    }
    
    // Calculate score (pass blank positions for proper scoring)
    const score = calculateScore(row, col, word, direction, newTiles, blankPositions);
    
    return { word, row, col, direction, score, newTiles, blankPositions: Array.from(blankPositions) };
}

function currentLetterPoints(letter) {
    const table = (typeof window !== 'undefined' && window.LETTER_POINTS) ? window.LETTER_POINTS : null;
    return table ? (table[letter] || 0) : 0;
}

function currentBingoBonus() {
    if (typeof window !== 'undefined' && typeof window.BINGO_BONUS === 'number') {
        return window.BINGO_BONUS;
    }
    return 40;
}

function centerScoresDouble() {
    return typeof window === 'undefined' || window.centerScoresDoubleWord !== false;
}

function calculateScore(row, col, word, direction, newTiles, blankPositions = new Set()) {
    const isHorizontal = direction === 'H';
    let wordScore = 0;
    let wordMultiplier = 1;
    
    // Check if bonus scoring is enabled (default to true if not set)
    const bonusEnabled = typeof window !== 'undefined' && window.bonusScoringEnabled !== undefined 
        ? window.bonusScoringEnabled 
        : true;
    
    for (let i = 0; i < word.length; i++) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        const letter = word[i];
        
        // Blank tiles (wildcards) are worth 0 points
        const isBlank = blankPositions.has(i);
        let letterScore = isBlank ? 0 : currentLetterPoints(letter);
        
        // Apply bonus only for new tiles (but blanks still worth 0 even with multiplier)
        // Center is double-word in Crossplay and Scrabble, and a normal square in Words with Friends
        if (bonusEnabled && newTiles.includes(i)) {
            const special = SPECIAL_SQUARES[`${r},${c}`];
            if (r === 7 && c === 7 && centerScoresDouble()) {
                wordMultiplier *= 2;
            } else if (special === 'dl') {
                letterScore *= 2;
            } else if (special === 'tl') {
                letterScore *= 3;
            } else if (special === 'dw') {
                wordMultiplier *= 2;
            } else if (special === 'tw') {
                wordMultiplier *= 3;
            }
        }
        
        wordScore += letterScore;
    }
    
    wordScore *= wordMultiplier;
    
    // Bingo: Crossplay 40, Scrabble 50, Words with Friends 35
    if (newTiles.length === 7) {
        wordScore += currentBingoBonus();
    }
    
    // Add cross-word scores
    for (const i of newTiles) {
        const r = isHorizontal ? row : row + i;
        const c = isHorizontal ? col + i : col;
        const isBlank = blankPositions.has(i);
        const crossScore = calculateCrossWordScore(r, c, word[i], direction, isBlank);
        wordScore += crossScore;
    }
    
    return wordScore;
}

function calculateCrossWordScore(row, col, letter, mainDirection, isBlankTile = false) {
    const isHorizontal = mainDirection === 'H';
    let crossWord = letter;
    let hasAdjacent = false;
    
    // Build cross word
    let startR = row, startC = col;
    
    // Track which position in the cross word is the new tile
    let newTileIndex = 0;
    
    // Look backwards
    let pos = isHorizontal ? row - 1 : col - 1;
    while (pos >= 0) {
        const r = isHorizontal ? pos : row;
        const c = isHorizontal ? col : pos;
        if (window.boardState[r][c]) {
            crossWord = window.boardState[r][c] + crossWord;
            newTileIndex++; // new tile shifts right as we prepend
            startR = isHorizontal ? pos : row;
            startC = isHorizontal ? col : pos;
            hasAdjacent = true;
            pos--;
        } else {
            break;
        }
    }
    
    // Look forwards
    pos = isHorizontal ? row + 1 : col + 1;
    while (pos < 15) {
        const r = isHorizontal ? pos : row;
        const c = isHorizontal ? col : pos;
        if (window.boardState[r][c]) {
            crossWord = crossWord + window.boardState[r][c];
            hasAdjacent = true;
            pos++;
        } else {
            break;
        }
    }
    
    if (!hasAdjacent) return 0;
    
    // Check if bonus scoring is enabled
    const bonusEnabled = typeof window !== 'undefined' && window.bonusScoringEnabled !== undefined 
        ? window.bonusScoringEnabled 
        : true;
    
    // Calculate cross word score
    let score = 0;
    let multiplier = 1;
    
    for (let i = 0; i < crossWord.length; i++) {
        const r = isHorizontal ? startR + i : startR;
        const c = isHorizontal ? startC : startC + i;
        const char = crossWord[i];
        
        // Check if this is the new tile position (which might be blank)
        const isNewTile = (isHorizontal && r === row) || (!isHorizontal && c === col);
        
        // Blank tiles are worth 0 points
        let letterScore = (isNewTile && isBlankTile) ? 0 : currentLetterPoints(char);
        
        // Only apply bonuses for the new tile position (if bonuses enabled)
        // Center is double-word in Crossplay and Scrabble, not in Words with Friends
        if (bonusEnabled && isNewTile) {
            const special = SPECIAL_SQUARES[`${r},${c}`];
            if (r === 7 && c === 7 && centerScoresDouble()) {
                multiplier *= 2;
            } else if (special === 'dl') letterScore *= 2;
            else if (special === 'tl') letterScore *= 3;
            else if (special === 'dw') multiplier *= 2;
            else if (special === 'tw') multiplier *= 3;
        }
        
        score += letterScore;
    }
    
    return score * multiplier;
}
